export type MasterIconName = keyof typeof MASTER_ICON_SVGS;

export type MasterIconProps = {
  name: MasterIconName;
  className?: string;
  style?: CSSProperties;
};

/**
 * Renders the per-master modal icon by name. Returns `null` for an unknown
 * name so callers can fall back to a generic placeholder.
 */
export function MasterIcon({ name, className, style }: MasterIconProps) {
  const markup = MASTER_ICON_SVGS[name];
  if (!markup) {
    return null;
  }
  return (
    <span
      className={className}
      style={{ display: "contents", ...style }}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: markup }}
    />
  );
}

export function isMasterIconName(value: string): value is MasterIconName {
  return Object.prototype.hasOwnProperty.call(MASTER_ICON_SVGS, value);
}
